/* one checked entry point per resource: nothing else may open the vault */
int vault_open(const char *path, int flags) {
    if (!policy_allows(path, flags)) { errno = EACCES; return -1; }
    struct open_how how = { .flags = (uint64_t)flags,
                            .resolve = RESOLVE_BENEATH | RESOLVE_NO_SYMLINKS };
    return (int)syscall(SYS_openat2, AT_FDCWD, path, &how, sizeof how);
}
/* the check and the open are one operation: no faccessat()-then-open() window */

